// The app's face on the home screen: NoteLetter's quill on the seal, named
// "NoteLetter". Until 2026-11-03 this app shipped Flutter's stock blue icon on
// iOS and Android and was called "NoteLetter Flutter". Nothing failed: an
// icon and a name are assets no Dart code reads.
//
// The icon is generated by tool/app_icons.mjs, from the ONE mark that web and
// the extension draw (NoteLetter-browserextension/assets/logo-mark.svg), in the
// seal's tokens. This test holds the committed files to those sources, so a
// re-run of `flutter create`, a hand-dropped PNG or a palette move goes red.
import 'dart:io';
import 'dart:typed_data';
import 'dart:ui' as ui;

import 'package:flutter/material.dart';
import 'package:flutter_app/theme/app_colors.dart';
import 'package:flutter_test/flutter_test.dart';

String _hex(Color c) =>
    '#${(c.toARGB32() & 0xFFFFFF).toRadixString(16).padLeft(6, '0').toUpperCase()}';

String _markPath() {
  final svg = File('../NoteLetter-browserextension/assets/logo-mark.svg')
      .readAsStringSync();
  final m = RegExp(r'<path[^>]*\sd="([^"]+)"').firstMatch(svg);
  expect(m, isNotNull, reason: 'logo-mark.svg has no path');
  return m!.group(1)!;
}

Future<ByteData> _rgba(String path, {required int size}) async {
  final codec = await ui.instantiateImageCodec(File(path).readAsBytesSync());
  final image = (await codec.getNextFrame()).image;
  expect(image.width, size, reason: '$path is ${image.width}px');
  return (await image.toByteData(format: ui.ImageByteFormat.rawRgba))!;
}

int _px(ByteData d, int size, int x, int y) {
  final i = (y * size + x) * 4;
  return (d.getUint8(i) << 16) | (d.getUint8(i + 1) << 8) | d.getUint8(i + 2);
}

int _rgb(Color c) => c.toARGB32() & 0xFFFFFF;

void main() {
  test('the Android adaptive icon draws the extension\'s mark in the seal tokens',
      () {
    const res = 'android/app/src/main/res';
    final fg = File('$res/drawable/ic_launcher_foreground.xml').readAsStringSync();
    final path = RegExp(r'android:pathData="([^"]+)"').firstMatch(fg)?.group(1);
    expect(path, _markPath(),
        reason: 'the quill is one path on every client; re-run tool/app_icons.mjs');
    expect(fg, contains('android:fillColor="${_hex(AppColors.primaryForeground)}"'),
        reason: 'the mark is --accent-fg (--paper-50)');
    final bg = File('$res/values/ic_launcher_background.xml').readAsStringSync();
    expect(bg, contains('>${_hex(AppColors.sealLight)}</color>'),
        reason: 'the tile is --seal (light), --brick-700');
    final adaptive = File('$res/mipmap-anydpi-v26/ic_launcher.xml').readAsStringSync();
    expect(adaptive, contains('@drawable/ic_launcher_foreground'));
    expect(adaptive, contains('@color/ic_launcher_background'));
    final manifest =
        File('android/app/src/main/AndroidManifest.xml').readAsStringSync();
    expect(manifest, contains('android:icon="@mipmap/ic_launcher"'));
  });

  testWidgets('the icon PNGs are the seal tile, not Flutter\'s stock icon',
      (tester) async {
    await tester.runAsync(() async {
      // iOS: one universal 1024, full-bleed and OPAQUE (iOS masks it, and the
      // App Store refuses alpha). PNG colour type 2 is RGB with no alpha.
      const set = 'ios/Runner/Assets.xcassets/AppIcon.appiconset';
      final contents = File('$set/Contents.json').readAsStringSync();
      expect(contents, contains('"AppIcon-1024.png"'));
      expect(contents, contains('"universal"'));
      final ios = File('$set/AppIcon-1024.png').readAsBytesSync();
      expect(ios[25], 2, reason: 'the iOS icon must have no alpha channel');
      final d = await _rgba('$set/AppIcon-1024.png', size: 1024);
      expect(_px(d, 1024, 0, 0), _rgb(AppColors.sealLight),
          reason: 'full-bleed --seal to the corner');
      expect(_px(d, 1024, 512, 512), _rgb(AppColors.primaryForeground),
          reason: 'the quill crosses the centre in --accent-fg');

      // Android legacy launchers: the rounded tile.
      const sizes = {
        'mdpi': 48, 'hdpi': 72, 'xhdpi': 96, 'xxhdpi': 144, 'xxxhdpi': 192,
      };
      for (final e in sizes.entries) {
        final p = 'android/app/src/main/res/mipmap-${e.key}/ic_launcher.png';
        final a = await _rgba(p, size: e.value);
        final s = e.value;
        expect(_px(a, s, s ~/ 2, s ~/ 2), _rgb(AppColors.primaryForeground),
            reason: '$p: the quill at the centre');
        expect(_px(a, s, s ~/ 2, 2), _rgb(AppColors.sealLight),
            reason: '$p: the seal tile at the top edge');
      }
    });
  });

  test('the app is called NoteLetter on the home screen and in the share sheet',
      () {
    // The Swift app that held the name is retired (ADR-175), so the suffix
    // that told the two apart has nothing left to distinguish.
    String displayName(String plist) {
      final m = RegExp(r'<key>CFBundleDisplayName</key>\s*<string>([^<]*)</string>')
          .firstMatch(File(plist).readAsStringSync());
      return m?.group(1) ?? '';
    }

    expect(displayName('ios/Runner/Info.plist'), 'NoteLetter');
    expect(displayName('ios/Share/Info.plist'), 'NoteLetter');
    final manifest =
        File('android/app/src/main/AndroidManifest.xml').readAsStringSync();
    expect(RegExp(r'<application[^>]*android:label="NoteLetter"').hasMatch(manifest),
        isTrue);
  });
}
